def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C'

    my_last, opp_last = history[-1]

    opp_c = 0
    my_c = 0
    for a, b in history:
        if b == 'C':
            opp_c += 1
        if a == 'C':
            my_c += 1
    opp_d = n - opp_c
    my_d = n - my_c

    # Strongly cooperative opponents: match cooperation, but exploit late.
    if opp_c >= n - 1:
        if n >= 95:
            return 'D'
        return 'C'

    # Track consecutive opponent responses.
    same_count = 1
    for i in range(n - 1, 0, -1):
        if history[i][1] == history[i - 1][1]:
            same_count += 1
        else:
            break

    # Identify a period-5 defector pattern (defects on positions 0,1,5,6,...).
    if n >= 6:
        periodic_hits = 0
        periodic_total = 0
        for i in range(n):
            if i % 5 < 2:
                periodic_total += 1
                if history[i][1] == 'D':
                    periodic_hits += 1
        if periodic_total > 0 and periodic_hits * 10 >= periodic_total * 7:
            if n % 5 < 2:
                return 'D'
            return 'C'

    # Opponent defection streak: punish but probe occasionally to recover.
    if opp_last == 'D' and same_count >= 5:
        if same_count <= 9 and rng.randint(0, 5) == 0:
            return 'C'
        return 'D'

    # Opponent cooperation streak: reciprocate, occasional late probe.
    if opp_last == 'C' and same_count >= 4:
        if n < 90 and same_count % 9 == 0 and rng.randint(0, 6) == 0:
            return 'D'
        return 'C'

    # If we have been cooperative and opponent suddenly defects once,
    # retaliate immediately to discourage exploitation.
    if opp_last == 'D' and my_last == 'C':
        return 'D'

    # If opponent defected and we also defected, continue pressure briefly,
    # then try to reopen cooperation if opponent has mixed history.
    if opp_last == 'D' and my_last == 'D':
        if my_d > opp_d + 3:
            return 'C'
        if rng.randint(0, 2) == 0:
            return 'C'
        return 'D'

    # If opponent just cooperated after we defected, return to cooperation.
    if opp_last == 'C' and my_last == 'D':
        return 'C'

    # Overall defection-heavy opponent: defect more, but not purely.
    if opp_d > n * 0.55:
        if rng.randint(0, 3) == 0:
            return 'C'
        return 'D'

    # In the final rounds, exploit highly cooperative opponents.
    if n >= 94:
        if opp_c > n * 0.7:
            return 'D'
        if opp_last == 'C':
            return 'D' if rng.randint(0, 1) == 0 else 'C'
        return 'D'

    # Core forgiving tit-for-tat: cooperate unless opponent just defected.
    if opp_last == 'C':
        return 'C'

    if rng.randint(0, 5) == 0 and opp_c + 1 >= opp_d:
        return 'C'
    return 'D'
